var MU = 398600.4418; // km^3/s^2 (Earth)
var r1 = parseFloat(DATA.r1), r2 = parseFloat(DATA.r2);
function vc(r) { return Math.sqrt(MU / r); }
function hohmann(r1, r2) {
  var at = (r1 + r2) / 2;
  var dv1 = Math.sqrt(MU * (2 / r1 - 1 / at)) - vc(r1);
  var dv2 = vc(r2) - Math.sqrt(MU * (2 / r2 - 1 / at));
  var t = Math.PI * Math.sqrt(Math.pow(at, 3) / MU);
  return { dv1: dv1, dv2: dv2, total: Math.abs(dv1) + Math.abs(dv2), t: t };
}
console.log("Maneuver: " + DATA.mtype);
console.log("From r=" + r1 + " km to r=" + r2 + " km (Earth, mu=" + MU + ")");
var h = hohmann(r1, r2);
console.log("  burn 1 (departure): " + h.dv1.toFixed(3) + " km/s");
console.log("  burn 2 (arrival):   " + h.dv2.toFixed(3) + " km/s");
console.log("  total delta-v:      " + h.total.toFixed(3) + " km/s");
console.log("  transfer time:      " + (h.t / 3600).toFixed(2) + " hours");
console.log("RESULT: Hohmann transfer computed with real two-body mechanics.");

